export const WORDS = [...new Set([...ORIGINAL_WORDS, ...EXTRA_WORDS])];
export const VALID_GUESSES = new Set([...guessDictionary, ...WORDS]);
// Preserve existing puzzles until the next UTC rollover after this update.
const EXPANDED_WORDS_START = Date.UTC(2026, 9, 12) / 86400000;
export function dailyWord(date = new Date()) {
  const day = Math.floor(
    Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) /
      86400000,
  );
  const pool = day < EXPANDED_WORDS_START ? ORIGINAL_WORDS : WORDS;
  return pool[(((day * 37 + 113) % pool.length) + pool.length) % pool.length];
}
export function wordColors(guess, answer) {
  const out = Array(5).fill("absent"),
    left = answer.split("");
  for (let i = 0; i < 5; i++)
    if (guess[i] === answer[i]) {
      out[i] = "correct";
      left[i] = null;
    }
  for (let i = 0; i < 5; i++)
    if (out[i] !== "correct") {
      const j = left.indexOf(guess[i]);
      if (j !== -1) {
        out[i] = "present";
        left[j] = null;
      }
    }
  return out;
}
export function slide2048(board, direction) {
  let grid = board.map((r) => [...r]),
    score = 0;
  const reverse = direction === "right" || direction === "down";
  for (let i = 0; i < 4; i++) {
    let row =
      direction === "left" || direction === "right"
        ? [...grid[i]]
        : grid.map((r) => r[i]);
    if (reverse) row.reverse();
    const nums = row.filter(Boolean),
      merged = [];
    for (let j = 0; j < nums.length; j++) {
      if (nums[j] === nums[j + 1]) {
        merged.push(nums[j] * 2);
        score += nums[j] * 2;
        j++;
      } else merged.push(nums[j]);
    }
    while (merged.length < 4) merged.push(0);
    if (reverse) merged.reverse();
    if (direction === "left" || direction === "right") grid[i] = merged;
    else grid.forEach((r, j) => (r[i] = merged[j]));
  }
  return {
    board: grid,
    score,
    changed: JSON.stringify(grid) !== JSON.stringify(board),
  };
}
export function has2048Moves(board) {
  return board.some((row, r) =>
    row.some(
      (v, c) =>
        !v || (c < 3 && v === row[c + 1]) || (r < 3 && v === board[r + 1][c]),
    ),
  );
}
export function winner(board) {
  const lines = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
  ];
  for (const [a, b, c] of lines)
    if (board[a] && board[a] === board[b] && board[a] === board[c])
      return board[a];
  return board.every(Boolean) ? "draw" : null;
}
export function connectWinner(board) {
  for (let r = 0; r < 6; r++)
    for (let c = 0; c < 7; c++)
      if (board[r][c])
        for (const [dr, dc] of [
          [0, 1],
          [1, 0],
          [1, 1],
          [1, -1],
        ])
          if (
            [1, 2, 3].every(
              (k) => board[r + k * dr]?.[c + k * dc] === board[r][c],
            )
          )
            return board[r][c];
  return board.flat().every(Boolean) ? "draw" : null;
}

export const SOLVED_PUZZLE = [
  ...Array.from({ length: 15 }, (_, i) => i + 1),
  0,
];
export function puzzleSolved(board) {
  return board.every((value, i) => value === SOLVED_PUZZLE[i]);
}
export function slidePuzzle(board, tileIndex) {
  const blank = board.indexOf(0);
  const distance =
    Math.abs(Math.floor(blank / 4) - Math.floor(tileIndex / 4)) +
    Math.abs((blank % 4) - (tileIndex % 4));
  if (tileIndex < 0 || tileIndex > 15 || distance !== 1) return board;
  const next = [...board];
  [next[blank], next[tileIndex]] = [next[tileIndex], next[blank]];
  return next;
}
export function shufflePuzzle(random = Math.random) {
  let board = [...SOLVED_PUZZLE],
    previous = -1;
  // Legal moves from the solved board always produce a solvable puzzle.
  for (let i = 0; i < 250; i++) {
    const blank = board.indexOf(0);
    const options = board
      .map((_, index) => index)
      .filter(
        (index) => index !== previous && slidePuzzle(board, index) !== board,
      );
    const tile = options[Math.floor(random() * options.length)];
    board = slidePuzzle(board, tile);
    previous = blank;
  }
  if (puzzleSolved(board)) board = slidePuzzle(board, 14);
  return board;
}
